// Tiny static file server for Habit Hatch. Serves public/ on localhost.
// Run: npm start   (PORT env var overrides the default 3000)

import http from 'node:http';
import { readFile } from 'node:fs/promises';
import { join, extname, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.ico': 'image/x-icon',
  '.webmanifest': 'application/manifest+json',
};

/**
 * Create an http.Server that serves files from `root`.
 * `/` maps to index.html; anything outside `root` or missing is a 404.
 * @param {string} root absolute path of the folder to serve
 * @returns {http.Server}
 */
export function createServer(root) {
  const base = resolve(root);
  return http.createServer(async (req, res) => {
    let pathname;
    try {
      pathname = decodeURIComponent(new URL(req.url, 'http://x').pathname);
    } catch {
      return send(res, 400, 'Bad request');
    }
    if (pathname.endsWith('/')) pathname += 'index.html';
    const file = resolve(join(base, pathname));
    if (file !== base && !file.startsWith(base + sep)) {
      return send(res, 404, 'Not found');
    }
    try {
      const body = await readFile(file);
      res.writeHead(200, {
        'Content-Type': TYPES[extname(file).toLowerCase()] ?? 'application/octet-stream',
        'Cache-Control': 'no-cache',
      });
      res.end(body);
    } catch {
      send(res, 404, 'Not found');
    }
  });
}

function send(res, status, text) {
  res.writeHead(status, { 'Content-Type': 'text/plain; charset=utf-8' });
  res.end(text);
}

// Start listening only when run directly (not when imported by tests).
if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const port = Number(process.env.PORT) || 3000;
  const publicDir = fileURLToPath(new URL('./public/', import.meta.url));
  createServer(publicDir).listen(port, '127.0.0.1', () => {
    console.log(`Habit Hatch running at http://127.0.0.1:${port}`);
  });
}

